-- EMOJI = "00" -> vert
-- EMOJI = "01" -> jaune
-- EMOJI = "10" -> rouge

-- NUMBER = "0000" -> 0
-- NUMBER = "0001" -> 1
-- ...
-- NUMBER = "1001" -> 9
-- NUMBER = "1011" -> nothing


LIBRARY IEEE;
USE IEEE.STD_LOGIC_1164.ALL;
USE IEEE.NUMERIC_STD.ALL;

ENTITY ROM_CHAR IS
PORT (
      CLOCK          : IN  STD_LOGIC;
      
      ADDR           : IN  std_logic_vector(11 DOWNTO 0);
      SEL            : IN  std_logic;
      NUMBER         : IN  std_logic_vector(3 DOWNTO 0);
      EMOJI          : IN  std_logic_vector(1 downto 0);
      
      DATA_OUT       : OUT STD_LOGIC_VECTOR(15 DOWNTO 0)
      );
END ROM_CHAR;

ARCHITECTURE Behavioral OF ROM_CHAR IS

  TYPE rom_emoji is array (0 TO 4095) of unsigned(15 downto 0);
  TYPE rom_emojis is array (0 to 2) of rom_emoji;
  
  signal memory_emoji : rom_emojis;
  
  type rom_char is array (0 to 95) of unsigned(15 downto 0);
  type rom_chars is array (0 to 9) of rom_char;
  
  signal memory_char : rom_chars;
  
  signal NUMBER_INT : integer range 0 to 9;
  
  
  ATTRIBUTE RAM_STYLE : string;
  ATTRIBUTE RAM_STYLE of memory_emoji: signal is "BLOCK";
  ATTRIBUTE RAM_STYLE of memory_char: signal is "BLOCK";

BEGIN

    NUMBER_INT <= 9 when unsigned(NUMBER)>"1001" else
                  to_integer(unsigned(NUMBER));

    PROCESS (CLOCK)
        BEGIN
        IF (CLOCK'event AND CLOCK = '1') THEN
            IF(SEL = '0') then 
                DATA_OUT <= STD_LOGIC_VECTOR(memory_char(NUMBER_INT)(to_integer(unsigned(ADDR))));
            ELSE 
                DATA_OUT <= STD_LOGIC_VECTOR(memory_emoji(to_integer(unsigned(EMOJI)))(to_integer(unsigned(ADDR))));
            END IF;
        END IF;
    END PROCESS;

